"use client";

import { useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { KeyboardEvent as ReactKeyboardEvent, PointerEvent as ReactPointerEvent, ReactNode } from "react";
import { AnimatePresence, animate, motion, useMotionValue, useReducedMotion } from "motion/react";
import type { Transition, ValueAnimationTransition, Variants } from "motion/react";
import { Command as CommandIcon, Search, X } from "lucide-react";
import { motionTokens } from "../lib/motion-tokens";
import { useNearestItem } from "../lib/fluid-hover";
import styles from "./command-palette.module.css";

export interface CommandItem { id: string; label: string; description?: string; group?: string; keywords?: string[]; icon?: ReactNode; shortcut?: string; }
export interface CommandPaletteProps { items: CommandItem[]; placeholder?: string; onSelect?: (item: CommandItem) => void; onClose?: () => void; label?: string; /** Focus the search field on mount, for a palette that opens on demand. */ autoFocus?: boolean; }

const enter: Transition = { duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter] };
const leave: Transition = { duration: motionTokens.duration.instant, ease: [...motionTokens.ease.standard] };
const GLIDE_ROWS = 6;
/** Rows fade out while the rest glide into their place; when the list snaps they leave at once so nothing overlaps the new rows. */
const rowExit: Variants = { exit: (glide: boolean) => ({ opacity: 0, transition: glide ? leave : { duration: 0 } }) };

export function CommandPalette({ items, placeholder = "Search commands", onSelect, onClose, label = "Command palette", autoFocus = false }: CommandPaletteProps) {
  const inputId = useId();
  const [query, setQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const [listHeight, setListHeight] = useState<number | "auto">("auto");
  const reduced = useReducedMotion();
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const pointer = useRef(false);
  const lastPointer = useRef({ x: -1, y: -1 });
  const highlightShown = useRef(false);
  const highlightY = useMotionValue(0);
  const highlightHeight = useMotionValue(0);
  const highlightOpacity = useMotionValue(0);
  const filtered = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return items;
    return items.filter(item => [item.label, item.description, item.group, ...(item.keywords ?? [])].filter(Boolean).join(" ").toLowerCase().includes(normalized));
  }, [items, query]);
  const groupedItems = useMemo(() => {
    const grouped = new Map<string, Array<{ item: CommandItem; index: number }>>();
    filtered.forEach((item, index) => {
      const group = item.group ?? "Actions";
      const entries = grouped.get(group) ?? [];
      entries.push({ item, index });
      grouped.set(group, entries);
    });
    return [...grouped.entries()];
  }, [filtered]);
  // When every remaining row moves within about a viewport, the list closes its gaps with a glide. A long jump (the first letters typed into a long list) snaps like a search result list instead of streaking rows through the frame; only the frame height morphs.
  const [shift, setShift] = useState({ list: filtered, glide: true });
  if (shift.list !== filtered) {
    const before = new Map(shift.list.map((item, index) => [item.id, index]));
    setShift({ list: filtered, glide: filtered.every((item, index) => Math.abs((before.get(item.id) ?? index) - index) <= GLIDE_ROWS) });
  }
  const glide = shift.glide && !reduced;
  const safeActiveIndex = activeIndex === null
    ? -1
    : Math.min(activeIndex, Math.max(filtered.length - 1, 0));
  const activeId = filtered[safeActiveIndex]?.id;

  useEffect(() => {
    if (autoFocus) inputRef.current?.focus({ preventScroll: true });
  }, [autoFocus]);

  useEffect(() => {
    const focusShortcut = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        inputRef.current?.focus();
      }
    };
    document.addEventListener("keydown", focusShortcut);
    return () => document.removeEventListener("keydown", focusShortcut);
  }, []);

  // The results frame follows the list height, so filtering closes or opens the gap instead of snapping.
  useLayoutEffect(() => {
    const list = listRef.current;
    if (!list) return;
    const observer = new ResizeObserver(([entry]) => setListHeight(Math.round(entry?.borderBoxSize?.[0]?.blockSize ?? list.offsetHeight)));
    observer.observe(list);
    return () => observer.disconnect();
  }, []);

  // Fluid hover: the mouse makes the nearest result active, group headings and padding included, and a click there runs it.
  const nearest = useNearestItem<HTMLDivElement>({ items: '[role="option"]', onPick: item => {
    const index = Number(item.dataset.index);
    if (index !== safeActiveIndex) { pointer.current = true; setActiveIndex(index); }
  } });
  function onListPointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    // Ignore the synthetic moves browsers send while the list scrolls under a still pointer.
    if (event.clientX === lastPointer.current.x && event.clientY === lastPointer.current.y) return;
    lastPointer.current = { x: event.clientX, y: event.clientY };
    nearest.onPointerMove(event);
  }

  // One highlight follows the active result: a spring for the pointer, a 70ms slide for arrow keys, a fade when it first appears.
  useLayoutEffect(() => {
    const node = activeId ? document.getElementById(`${inputId}-${activeId}`) : null;
    if (!node) {
      highlightShown.current = false;
      animate(highlightOpacity, 0, { duration: reduced ? 0 : .1 });
      return;
    }
    const move: ValueAnimationTransition<number> = !highlightShown.current || reduced ? { duration: 0 } : pointer.current ? motionTokens.spring.snappy : { duration: motionTokens.duration.instant, ease: [...motionTokens.ease.enter] };
    // Rows sit inside positioned groups, so their offset is summed up to the list (layout transforms stay out of it).
    let top = 0;
    for (let element: HTMLElement | null = node; element && element !== listRef.current; element = element.offsetParent as HTMLElement | null) top += element.offsetTop + (element === node ? 0 : element.clientTop);
    animate(highlightY, top, move);
    animate(highlightHeight, node.offsetHeight, move);
    animate(highlightOpacity, 1, { duration: reduced ? 0 : .08 });
    highlightShown.current = true;
  }, [activeId, inputId, reduced, highlightY, highlightHeight, highlightOpacity]);

  useEffect(() => {
    if (!activeId) return;
    document.getElementById(`${inputId}-${activeId}`)?.scrollIntoView({ block: "nearest" });
  }, [activeId, inputId]);

  function choose(item: CommandItem) {
    onSelect?.(item);
    setQuery("");
    setActiveIndex(null);
    inputRef.current?.focus();
  }
  function handleKeyDown(event: ReactKeyboardEvent<HTMLInputElement>) {
    pointer.current = false;
    if (event.key === "ArrowDown") { event.preventDefault(); setActiveIndex(index => Math.min((index ?? -1) + 1, Math.max(filtered.length - 1, 0))); }
    if (event.key === "ArrowUp") { event.preventDefault(); setActiveIndex(index => Math.max((index ?? filtered.length) - 1, 0)); }
    if (event.key === "Home") { event.preventDefault(); setActiveIndex(0); }
    if (event.key === "End") { event.preventDefault(); setActiveIndex(Math.max(filtered.length - 1, 0)); }
    // Enter runs the highlighted result; after typing, with nothing highlighted yet, it runs the top match.
    const target = filtered[safeActiveIndex] ?? (query ? filtered[0] : undefined);
    if (event.key === "Enter" && target) { event.preventDefault(); choose(target); }
    if (event.key === "Escape") {
      event.preventDefault();
      if (query) { setQuery(""); setActiveIndex(null); }
      else onClose?.();
    }
  }

  return <motion.div className={styles.palette} initial={reduced ? false : { opacity: 0, y: 6, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }} transition={reduced ? { duration: 0 } : { default: motionTokens.spring.smooth, opacity: { duration: motionTokens.duration.fast, ease: [...motionTokens.ease.enter] } }}>
    <div className={styles.searchRow}>
      <span className={styles.searchIcon}><Search width={18} height={18} strokeWidth={1.75} aria-hidden="true"/></span>
      <label className={styles.visuallyHidden} htmlFor={inputId}>{label}</label>
      <input ref={inputRef} id={inputId} role="combobox" aria-autocomplete="list" aria-expanded="true" aria-controls={`${inputId}-results`} aria-activedescendant={activeId ? `${inputId}-${activeId}` : undefined} value={query} onChange={event => { setQuery(event.target.value); setActiveIndex(null); }} onKeyDown={handleKeyDown} placeholder={placeholder} autoComplete="off"/>
      <AnimatePresence mode="popLayout" initial={false}>
        {query ? <motion.button key="clear" className={styles.clearButton} type="button" aria-label="Clear search" onClick={() => { setQuery(""); setActiveIndex(null); inputRef.current?.focus(); }} initial={reduced ? false : { opacity: 0, scale: .6, filter: `blur(${motionTokens.blur.subtle}px)` }} animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }} exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, scale: .6, filter: `blur(${motionTokens.blur.subtle}px)`, transition: leave }} transition={reduced ? { duration: 0 } : { default: motionTokens.spring.snappy, opacity: { duration: motionTokens.duration.instant } }}><X width={15} height={15} aria-hidden="true"/></motion.button> : null}
      </AnimatePresence>
      {onClose ? <button className={styles.closeButton} type="button" aria-label="Close command palette" onClick={onClose}>Esc</button> : null}
      <kbd className={styles.commandKey}>⌘ K</kbd>
    </div>
    <motion.div className={styles.resultsFrame} initial={false} animate={{ height: listHeight }} transition={reduced ? { duration: 0 } : motionTokens.spring.smooth}>
      <motion.div ref={listRef} layoutScroll id={`${inputId}-results`} className={styles.results} role="listbox" aria-label="Command results" onPointerMove={onListPointerMove} onClick={nearest.onClick}>
        <motion.span className={styles.highlight} style={{ y: highlightY, height: highlightHeight, opacity: highlightOpacity }} aria-hidden="true"/>
        {/* Results leave before the empty state arrives, so the frame makes one height change instead of two. */}
        <AnimatePresence mode="wait" initial={false}>
          {filtered.length ? <motion.div key="results" initial={reduced ? false : { opacity: 0 }} animate={{ opacity: 1 }} exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, transition: leave }} transition={enter}>
            {/* Filtered-out rows pop out of the flow as they fade, so the rest glide up and the frame starts closing on the same keystroke. */}
            <AnimatePresence mode="popLayout" initial={false} custom={glide}>
              {groupedItems.map(([group, entries]) => <motion.div layout={glide ? "position" : false} className={styles.group} role="group" aria-label={group} key={group} variants={rowExit} initial={reduced ? false : { opacity: 0 }} animate={{ opacity: 1 }} exit="exit" transition={reduced ? { duration: 0 } : { default: enter, layout: motionTokens.spring.smooth }}>
                <span className={styles.groupHeading} aria-hidden="true">{group}</span>
                <AnimatePresence mode="popLayout" initial={false} custom={glide}>{entries.map(({ item, index }) => <motion.button layout={glide ? "position" : false} key={item.id} id={`${inputId}-${item.id}`} className={`${styles.result} ${index === safeActiveIndex ? styles.activeResult : ""}`} type="button" role="option" aria-selected={index === safeActiveIndex} onClick={() => choose(item)} data-index={index} variants={rowExit} initial={reduced ? false : { opacity: 0 }} animate={{ opacity: 1 }} exit="exit" transition={reduced ? { duration: 0 } : { default: enter, layout: motionTokens.spring.smooth }}><span className={styles.itemIcon} aria-hidden="true">{item.icon ?? <CommandIcon width={16} height={16}/>}</span><span className={styles.resultCopy}><strong>{item.label}</strong>{item.description && <small>{item.description}</small>}</span>{item.shortcut && <kbd className={styles.shortcut}>{item.shortcut}</kbd>}</motion.button>)}</AnimatePresence>
              </motion.div>)}
            </AnimatePresence>
          </motion.div> : <motion.div key="empty" className={styles.empty} initial={reduced ? false : { opacity: 0, y: 6, filter: `blur(${motionTokens.blur.subtle}px)` }} animate={{ opacity: 1, y: 0, filter: "blur(0px)" }} exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, y: -4, transition: leave }} transition={enter}><span><Search width={20} height={20} aria-hidden="true"/></span><strong>No matching actions</strong><small>Try a different word or clear the search.</small></motion.div>}
        </AnimatePresence>
      </motion.div>
    </motion.div>
  </motion.div>;
}

export default CommandPalette;

.palette {
  width: 100%;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-container);
  background: var(--surface);
  box-shadow: var(--shadow-floating);
  transform-origin: top center;
}

.searchRow {
  position: relative;
  display: flex;
  min-height: 54px;
  align-items: center;
  gap: var(--space-group);
  padding: var(--space-related) var(--space-inset);
  border-bottom: 1px solid var(--border-subtle);
  transition: background var(--duration-fast) var(--ease-standard);
}

.searchRow:focus-within { background: var(--surface-muted); }
.searchIcon, .itemIcon { display: grid; flex: none; place-items: center; color: var(--text-muted); }
.searchIcon { width: 22px; height: 22px; }
.searchRow input { min-width: 0; flex: 1; border: 0; outline: 0; background: transparent; color: var(--foreground); font: inherit; font-size: var(--text-sm); }
.searchRow input::placeholder { color: var(--text-muted); }
.searchRow input:focus-visible { outline: none; }

.commandKey, .shortcut {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  border: 1px solid var(--border);
  border-radius: var(--radius-detail);
  background: var(--surface-muted);
  color: var(--text-muted);
  font-family: inherit;
  font-size: var(--text-xs);
  font-weight: 500;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.commandKey { min-width: 38px; height: 24px; padding: 0 var(--space-related); gap: var(--space-hair); }
.clearButton { display: grid; width: 24px; height: 24px; flex: none; place-items: center; border: 0; border-radius: var(--radius-detail); background: transparent; color: var(--text-muted); cursor: pointer; transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard); }
@media (hover: hover) and (pointer: fine) { .clearButton:hover, .closeButton:hover { background: var(--surface); color: var(--foreground); } }
.clearButton:active, .closeButton:active { background: var(--surface); color: var(--foreground); }
.closeButton { display: grid; min-width: 27px; height: 24px; flex: none; place-items: center; border: 1px solid var(--border-subtle); border-radius: var(--radius-detail); background: transparent; color: var(--text-muted); padding: 0 var(--space-related); font: inherit; font-size: var(--text-xs); font-weight: 500; line-height: 1; cursor: pointer; transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard); }

/* The frame animates to the list height; the list keeps its own scroll. */
.resultsFrame { overflow: hidden; }
.results { position: relative; max-height: 342px; overflow: auto; padding: var(--space-related) var(--space-related); }
.highlight { position: absolute; top: 0; right: var(--space-related); left: var(--space-related); border-radius: var(--radius-detail); background: var(--surface-muted); opacity: 0; pointer-events: none; }
/* Groups are positioned so a row that pops out of the flow is placed against the same box it was measured in, even mid-glide. */
.group { position: relative; }
.group + .group { margin-top: var(--space-related); }
.groupHeading { display: block; padding: var(--space-related) var(--space-related) var(--space-tight); color: var(--text-muted); font-size: var(--text-xs); font-weight: 500; line-height: var(--leading-body); }

/* One line per result: the title, then its description in muted text, so the list stays short and scannable. */
.result { position: relative; display: flex; width: 100%; min-height: 34px; align-items: center; gap: var(--space-group); border: 0; border-radius: var(--radius-detail); padding: 0 var(--space-related); background: transparent; color: var(--foreground); text-align: left; cursor: pointer; }
/* The active row is drawn by the shared highlight; the row itself only tints its icon and arrow. */
.itemIcon { transition: color var(--duration-fast) var(--ease-standard); }
.itemIcon { display: grid; width: 16px; height: 16px; flex: none; place-items: center; color: var(--text-muted); }
.itemIcon svg { width: 16px; height: 16px; }
.resultCopy { display: flex; min-width: 0; flex: 1; align-items: baseline; gap: var(--space-related); }
.resultCopy strong, .resultCopy small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.resultCopy strong { flex: none; max-width: 100%; }
.resultCopy small { min-width: 0; }
.resultCopy strong { font-size: var(--text-sm); font-weight: 500; }
.resultCopy small { color: var(--text-muted); font-size: var(--text-xs); }
.shortcut { min-width: 18px; height: 18px; padding: 0 var(--space-tight); border-color: transparent; border-radius: var(--radius-detail); font-size: var(--text-xs); }
.activeResult .itemIcon { color: var(--foreground); }
.empty { display: grid; justify-items: center; gap: var(--space-tight); padding: var(--space-section) var(--space-group) var(--space-block); text-align: center; }
.empty > span { display: grid; width: 32px; height: 32px; place-items: center; margin-bottom: var(--space-tight); color: var(--text-muted); }
.empty strong { font-size: var(--text-sm); font-weight: 500; }
.empty small { color: var(--text-muted); font-size: var(--text-xs); }
.visuallyHidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

@media (max-width: 480px) {
  .searchRow { gap: var(--space-related); padding: var(--space-related) var(--space-group); }
  .results { padding: var(--space-related); }
  .highlight { right: var(--space-related); left: var(--space-related); }
  .result { gap: var(--space-related); }
  .shortcut, .commandKey { display: none; }
  }

@media (max-width: 340px) {
    .result { padding-inline: var(--space-related); }
}

@media (prefers-reduced-motion: reduce) {
  .searchRow, .itemIcon, .clearButton, .closeButton { transition: none; }
}

"use client";

/**
 * Fluid hover: in a set of items (a menu, a list, tabs, a grid), the item nearest the pointer is lit, even while the
 * pointer is in a gap, the padding or past the last item, and one highlight springs between items. A click in a gap goes
 * to the lit item, so what is lit is what a click hits. A new pointer entry fades the highlight in where it lands instead
 * of sliding it over from the last item. The keyboard moves it without travel, and reduced motion keeps the fade but
 * drops the travel.
 *
 *   const list = useRef<HTMLUListElement>(null);
 *   const hover = useFluidHover(list, { items: "[data-item]" });
 *   <ul ref={list} className={styles.list} {...hover.handlers}>      // .list { position: relative }
 *     <FluidHoverHighlight hover={hover} className={styles.highlight} />
 *     …items…
 *   </ul>
 *
 * Adapted from Fluid Functionalism's use-fluid-hover and fluid-hover-highlight by Micka Touillaud (MIT),
 * https://github.com/mickadesign/fluid-functionalism. Items are found by a selector instead of registering themselves,
 * so a component adopts it without changing its items.
 */
import { useEffect, useEffectEvent, useRef, useState } from "react";
import type { FocusEvent, MouseEvent, PointerEvent, RefObject } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "./motion-tokens";

/** An item's box in the container's own layout space (unaffected by transforms or scrolling). */
export interface FluidRect { top: number; left: number; width: number; height: number }

export interface FluidHoverState {
  /** Where the highlight sits, or null when nothing is lit. */
  rect: FluidRect | null;
  /** The lit item. */
  item: HTMLElement | null;
  /** False when the highlight should jump (keyboard, a resize) rather than travel. */
  glide: boolean;
  /** Steps on each new pointer entry, so the highlight fades in where it lands. */
  session: number;
}

export interface FluidHoverOptions {
  /** Selector for the items inside the container. */
  items: string;
  /** "y" for lists (default), "x" for a row of tabs, "xy" for grids. */
  axis?: "x" | "y" | "xy";
  /** Items the highlight skips (and a gap click never activates). Defaults to disabled or aria-disabled items. */
  isItemDisabled?: (item: HTMLElement) => boolean;
  /** "skip" (default) lights the nearest enabled item even over a disabled one; "clear" lights nothing over a disabled item (a calendar's unavailable days). */
  disabled?: "skip" | "clear";
  /** Route a click in a gap to the lit item. On by default; turn it off where empty space should stay inert. */
  gapClick?: boolean;
  /** Light the item that receives keyboard focus. On by default. */
  followFocus?: boolean;
}

const defaultDisabled = (item: HTMLElement) =>
  item.matches(":disabled, [aria-disabled='true'], [data-disabled]");

/** Controls that sit between items keep their own clicks. */
const CONTROL = "input, textarea, select, button, a, summary, [contenteditable], [role='textbox'], [role='searchbox'], [role='button']";

/** The item's box relative to the container, summing offsets through positioned ancestors in between. */
export function rectOf(item: HTMLElement, container: HTMLElement): FluidRect {
  let top = item.offsetTop, left = item.offsetLeft;
  let parent = item.offsetParent as HTMLElement | null;
  while (parent && parent !== container && container.contains(parent)) {
    top += parent.offsetTop + parent.clientTop;
    left += parent.offsetLeft + parent.clientLeft;
    parent = parent.offsetParent as HTMLElement | null;
  }
  return { top, left, width: item.offsetWidth, height: item.offsetHeight };
}

/**
 * The item the pointer is inside, or else the one whose edge is nearest along the axis (both axes for a grid). Edges, not
 * centres, so a gap next to a wide item still lights the item the pointer is closer to.
 */
export function pickNearest(items: HTMLElement[], x: number, y: number, axis: "x" | "y" | "xy"): HTMLElement | null {
  let nearest: HTMLElement | null = null, best = Infinity;
  for (const item of items) {
    const r = item.getBoundingClientRect();
    if (!r.width && !r.height) continue;
    if (x >= r.left && x <= r.right && y >= r.top && y <= r.bottom) return item;
    const dx = Math.max(r.left - x, 0, x - r.right), dy = Math.max(r.top - y, 0, y - r.bottom);
    const distance = axis === "x" ? dx : axis === "y" ? dy : Math.hypot(dx, dy);
    if (distance < best) { best = distance; nearest = item; }
  }
  return nearest;
}

/** Hands a gap click to the item as a real mouse click (detail, modifiers and coordinates kept), so the item reads it as a pointer press, not a keyboard one. */
function forwardClick(item: HTMLElement, event: MouseEvent<HTMLElement>) {
  const { detail, clientX, clientY, screenX, screenY, ctrlKey, shiftKey, altKey, metaKey, button, buttons } = event;
  item.dispatchEvent(new globalThis.MouseEvent("click", { bubbles: true, cancelable: true, composed: true, view: window, detail, clientX, clientY, screenX, screenY, ctrlKey, shiftKey, altKey, metaKey, button, buttons }));
}

/** Whether an event happened inside the element whose handler hears it, not in a portalled child (a submenu, a tooltip). */
const isOwn = (event: { currentTarget: EventTarget; target: EventTarget }) =>
  !(event.currentTarget instanceof Node) || !(event.target instanceof Node) || event.currentTarget.contains(event.target);

export function useFluidHover<T extends HTMLElement>(container: RefObject<T | null>, options: FluidHoverOptions) {
  const { items: selector, axis = "y", isItemDisabled = defaultDisabled, disabled = "skip", gapClick = true, followFocus = true } = options;
  const [state, setState] = useState<FluidHoverState>({ rect: null, item: null, glide: false, session: 0 });
  const current = useRef(state);
  const pointer = useRef(false);
  const entering = useRef(false);
  const frame = useRef(0);

  function commit(next: FluidHoverState) {
    const prev = current.current;
    if (prev.item === next.item && prev.session === next.session && sameRect(prev.rect, next.rect)) return;
    current.current = next;
    setState(next);
  }

  function light(item: HTMLElement | null, glide: boolean) {
    const root = container.current;
    if (!root || !item) return commit({ ...current.current, rect: null, item: null, glide });
    let session = current.current.session;
    if (entering.current) { entering.current = false; session += 1; }
    commit({ rect: rectOf(item, root), item, glide: glide && session === current.current.session, session });
  }

  const enabledItems = () => {
    const root = container.current;
    return root ? [...root.querySelectorAll<HTMLElement>(selector)].filter(item => !isItemDisabled(item)) : [];
  };

  // The lit item can move under a still highlight (a resize, content above it changing): follow it without travel.
  const follow = useEffectEvent(() => { const { item } = current.current; if (item?.isConnected) light(item, false); });
  useEffect(() => {
    const root = container.current;
    if (!root || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => follow());
    observer.observe(root);
    return () => observer.disconnect();
  }, [container]);
  useEffect(() => () => cancelAnimationFrame(frame.current), []);

  const handlers = {
    onMouseEnter: () => { entering.current = true; },
    onMouseMove: (event: MouseEvent<T>) => {
      if (!isOwn(event)) return;
      pointer.current = true;
      const { clientX, clientY } = event;
      cancelAnimationFrame(frame.current);
      frame.current = requestAnimationFrame(() => {
        const over = disabled === "clear" ? document.elementFromPoint(clientX, clientY)?.closest<HTMLElement>(selector) : null;
        light(over && isItemDisabled(over) ? null : pickNearest(enabledItems(), clientX, clientY, axis), true);
      });
    },
    onMouseLeave: () => { cancelAnimationFrame(frame.current); entering.current = false; light(null, false); },
    onKeyDownCapture: () => { pointer.current = false; },
    onFocus: (event: FocusEvent<T>) => {
      if (!followFocus || pointer.current || !isOwn(event)) return;
      const item = event.target instanceof HTMLElement ? event.target.closest<HTMLElement>(selector) : null;
      if (item && container.current?.contains(item) && !isItemDisabled(item)) light(item, false);
    },
    onBlur: (event: FocusEvent<T>) => {
      if (!pointer.current && !event.currentTarget.contains(event.relatedTarget as Node | null)) light(null, false);
    },
    onClick: (event: MouseEvent<T>) => {
      if (!gapClick || !isOwn(event)) return;
      const target = event.target as Element;
      if (!target.isConnected || target.closest(selector) || target.closest(CONTROL)) return;
      const { item } = current.current;
      if (item?.isConnected && !isItemDisabled(item)) forwardClick(item, event);
    },
  };

  /** Clears the highlight at once, such as when a menu opens again. */
  const reset = () => { cancelAnimationFrame(frame.current); entering.current = true; light(null, false); };

  return { ...state, handlers, reset, light };
}

export interface NearestItemOptions extends Omit<FluidHoverOptions, "followFocus"> {
  /** Called with the nearest enabled item as the mouse moves over the container. */
  onPick: (item: HTMLElement) => void;
}

/**
 * Fluid hover's picking without its highlight, for a list that already keeps its own active item and highlight (a listbox
 * with aria-activedescendant, a roving list): the mouse picks the nearest enabled item, gaps and padding included, and a
 * click in a gap goes to that item. Spread the result on the container.
 */
// A hook only so callbacks that touch refs can be passed during render; it keeps no state.
export function useNearestItem<T extends HTMLElement>({ items: selector, axis = "y", isItemDisabled = defaultDisabled, gapClick = true, onPick }: NearestItemOptions) {
  const nearest = (event: MouseEvent<T>) => {
    if (!isOwn(event)) return null;
    const items = [...event.currentTarget.querySelectorAll<HTMLElement>(selector)].filter(item => !isItemDisabled(item));
    return pickNearest(items, event.clientX, event.clientY, axis);
  };
  return {
    onPointerMove: (event: PointerEvent<T>) => { if (event.pointerType !== "mouse") return; const item = nearest(event); if (item) onPick(item); },
    onClick: (event: MouseEvent<T>) => {
      if (!gapClick) return;
      const target = event.target as Element;
      if (!target.isConnected || target.closest(selector) || target.closest(CONTROL)) return;
      const item = nearest(event);
      if (item) forwardClick(item, event);
    },
  };
}

const sameRect = (a: FluidRect | null, b: FluidRect | null) =>
  a === b || (!!a && !!b && a.top === b.top && a.left === b.left && a.width === b.width && a.height === b.height);

export interface FluidHoverHighlightProps {
  /** The state from useFluidHover (or any { rect, glide, session }). */
  hover: Pick<FluidHoverState, "rect" | "glide" | "session">;
  /** Radius, fill, z-index. The container must be position: relative; the highlight is placed at its top-left corner. */
  className?: string;
  /** Extra attributes for styling, such as data-tone. */
  tone?: string;
}

/** The one highlight a fluid hover set renders: it springs between items on transforms, and fades in and out. */
export function FluidHoverHighlight({ hover, className, tone }: FluidHoverHighlightProps) {
  const reduced = useReducedMotion() ?? false;
  const { rect, glide, session } = hover;
  const place = rect ? { x: rect.left, y: rect.top, width: rect.width, height: rect.height } : undefined;
  return (
    <AnimatePresence initial={false}>
      {place ? (
        <motion.span key={session} className={className} data-tone={tone} aria-hidden="true"
          style={{ position: "absolute", top: 0, left: 0, pointerEvents: "none" }}
          initial={{ opacity: 0, ...place }}
          animate={{ opacity: 1, ...place }}
          exit={{ opacity: 0, transition: motionTokens.spring.fast.exit }}
          transition={{ default: glide && !reduced ? motionTokens.spring.fast : { duration: 0 }, opacity: { duration: motionTokens.duration.fast } }} />
      ) : null}
    </AnimatePresence>
  );
}
